  'advanced.sprite_installed': ["Your sprite library is now in use: {forms} forms, {species} species{refused}","Ya se usa tu biblioteca de sprites: {forms} formas, {species} especies{refused}","已使用个人贴图库：{forms} 种形态，{species} 个物种{refused}"],
