  'ui.performance': ["Performance","Rendimiento","性能"],
  'performance.intro': ["Choose how Companion balances artwork and rendering work. Profiles do not change game data or available tools.","Elige cómo Companion equilibra las ilustraciones y el trabajo de renderizado. Los perfiles no cambian los datos del juego ni las herramientas disponibles.","选择 Companion 如何平衡图像显示和渲染开销。配置不会更改游戏数据或可用工具。"],
  'performance.profile': ["Performance profile","Perfil de rendimiento","性能配置"],
  'performance.lightweight': ["Lightweight","Ligero","轻量"],
  'performance.balanced': ["Balanced","Equilibrado","均衡"],
  'performance.quality': ["Full quality","Máxima calidad","完整画质"],
  'performance.custom': ["Custom","Personalizado","自定义"],
  'performance.lightweight_help': ["Smaller item batches; static artwork by default.","Lotes de objetos más pequeños; imágenes estáticas por defecto.","较小的道具加载批次；默认使用静态图像。"],
  'performance.balanced_help': ["Recommended: moderate item batches and normal sprite defaults.","Recomendado: lotes moderados de objetos y ajustes de sprites habituales.","推荐：适中的道具加载批次及常规精灵图默认设置。"],
  'performance.quality_help': ["Larger item batches and animated Pokédex grid by default.","Lotes de objetos más grandes y cuadrícula de la Pokédex animada por defecto.","较大的道具加载批次，图鉴网格默认使用动画。"],
  'performance.custom_help': ["Choose your own item batch size and animation defaults.","Elige el tamaño de lote y las animaciones predeterminadas.","自行选择道具加载批次大小及默认动画行为。"],
  'performance.batch': ["Item loading batch","Lote de carga de objetos","道具加载批次"],
  'performance.batch_help': ["Smaller batches create fewer item cards at once. The entire catalog remains searchable.","Los lotes pequeños crean menos tarjetas a la vez. Se puede buscar en todo el catálogo.","较小的批次每次创建更少的道具卡片，仍可搜索完整目录。"],
  'performance.small': ["Small","Pequeño","小"],
  'performance.normal': ["Normal","Normal","正常"],
  'performance.large': ["Large","Grande","大"],
  'performance.motion': ["Default artwork motion","Animación predeterminada","默认图像动画"],
  'performance.motion_help': ["Applies only where you have not selected an explicit sprite animation preference.","Solo se aplica donde no hayas elegido una preferencia explícita de animación.","仅在未明确设置精灵图动画偏好的地方生效。"],
  'performance.conservative': ["Conservative (static)","Conservadora (estática)","保守（静态）"],
  'performance.standard': ["Standard","Estándar","标准"],
  'performance.enhanced': ["Enhanced (animated grid)","Mejorada (cuadrícula animada)","增强（网格动画）"],
  'performance.overrides': ["Your explicit Pokémon & sprites and individual popout preferences still take priority. System-wide animation settings still apply.","Tus preferencias explícitas de Pokémon y sprites y de cada ventana flotante tienen prioridad. Los ajustes globales de animación siguen aplicándose.","你明确设置的宝可梦与精灵图偏好及各浮动窗口偏好仍优先。全局动画设置仍然生效。"],
  'performance.always': ["Memory cleanup, lazy loading and hidden Pokédex grid animation pausing stay enabled in every profile. Live alerts and timers are unchanged.","La limpieza de memoria, la carga diferida y la pausa de animaciones de la cuadrícula oculta de la Pokédex permanecen activas en todos los perfiles. Los avisos y temporizadores no cambian.","所有配置均启用内存清理、按需加载以及隐藏图鉴网格动画暂停。实时提醒和计时器不变。"],
  'performance.reset': ["Restore Balanced defaults","Restaurar ajustes equilibrados","恢复均衡默认设置"],
  'settings.cap_browser': ["Browser mode: popouts open as browser windows. Pin/always-on-top, window opacity and native toasts need the native shell (PySide6).","Modo navegador: las ventanas flotantes se abren en el navegador. La fijación, la opacidad de ventana y los avisos nativos requieren la interfaz nativa (PySide6).","浏览器模式：浮动窗口通过浏览器打开。置顶、窗口不透明度和原生通知需要原生窗口界面（PySide6）。"],
  'settings.cap_wayland': ["Native Wayland: the compositor controls window position and stacking, so Pin and position restore are disabled. Relaunch with ./run.sh --xwayland (or Settings › Window backend) to enable them.","Wayland nativo: el compositor controla la posición y el orden de las ventanas, por lo que la fijación y la restauración de posición están desactivadas. Reinicia con ./run.sh --xwayland (o Ajustes › Sistema de ventanas) para activarlas.","原生 Wayland：合成器控制窗口位置和层叠顺序，因此置顶和位置恢复已禁用。使用 ./run.sh --xwayland（或设置 › 窗口后端）重新启动以启用。"],
  'settings.cap_pin': ["Pin keeps a popout above normal windows. Exclusive-fullscreen games may still cover it — use windowed/borderless PokeMMO.","La fijación mantiene las ventanas flotantes sobre las normales. Los juegos en pantalla completa exclusiva aún pueden cubrirlas: usa PokeMMO en ventana o sin bordes.","置顶可让浮动窗口位于普通窗口之上。独占全屏游戏仍可能遮挡它；请使用 PokeMMO 的窗口或无边框模式。"],
  'settings.cap_tray': ["No system tray found: closing the main window quits the Companion.","No se encontró la bandeja del sistema: cerrar la ventana principal cierra Companion.","未找到系统托盘：关闭主窗口会退出 Companion。"],
