  'toolui.quick_no': ["After turn 1 ×1","Después del turno 1 ×1","第 1 回合后 ×1"],
  'toolui.timer': ["1 + turns passed × 0.3, max ×4 (turn {turn})","1 + turnos transcurridos × 0,3, máximo ×4 (turno {turn})","1 + 已过回合数 × 0.3，最高 ×4（第 {turn} 回合）"],
  'toolui.repeat_yes': ["Already registered as caught ×3","Ya registrado como capturado ×3","已登记为捕获 ×3"],
  'toolui.repeat_no': ["Not caught before ×1","No capturado anteriormente ×1","此前未捕获 ×1"],
