  'toolui.dream_no': ["Target awake ×1","Objetivo despierto ×1","目标未睡眠 ×1"],
  'toolui.luxury': ["×1 (raises friendship only)","×1 (solo aumenta la amistad)","×1（仅提高亲密度）"],
  'toolui.catch_rate_error': ["catch rate must be 1–255","La tasa de captura debe estar entre 1 y 255","捕获率必须为 1–255"],
  'toolui.hp_error': ["HP must be 1 ≤ current ≤ max","Los PS deben cumplir 1 ≤ actuales ≤ máximos","HP 必须满足 1 ≤ 当前值 ≤ 最大值"],
  'toolui.status_error': ["Unknown status","Estado desconocido","未知状态"],
  'toolui.iv_error': ["IV must be 0–31","Los IV deben estar entre 0 y 31","个体值必须为 0–31"],
  'toolui.ev_error': ["EV must be 0–252","Los EV deben estar entre 0 y 252","努力值必须为 0–252"],
