  'errorui.number': ["{field} must be a number","{field} debe ser un número","{field} 必须是数字"],
  'refui.source_0': ["PikaMMO — Legendary raids in PokeMMO (community guide; mechanics \"as of March 2026\")","PikaMMO — Incursiones legendarias en PokeMMO (guía de la comunidad; mecánicas de marzo de 2026)","PikaMMO — PokeMMO 传说宝可梦团体战（社区攻略；机制截至 2026 年 3 月）"],
  'refui.source_1': ["MMOBreeder — Virizion (raid at Rumination Field, Pinwheel Forest; \"available all year\")","MMOBreeder — Virizion (incursión en el Campo de la Meditación, Bosque Azulejo; disponible todo el año)","MMOBreeder — 毕力吉翁（矢车森林思索之原团体战；全年开放）"],
  'refui.source_2': ["Official forum — The Ultimate Legendary Guide (community; raids section edited 21 Feb 2026, per phase-4 research)","Foro oficial — The Ultimate Legendary Guide (comunidad; sección de incursiones editada el 21 de febrero de 2026, según la fase 4 de investigación)","官方论坛 — The Ultimate Legendary Guide（社区攻略；据第四阶段研究，团体战章节于 2026 年 2 月 21 日编辑）"],
  'refui.source_3': ["Official forum — Perfect Your Pokédex: everything you can register (community; says Cobalion, Terrakion and Virizion were added as permanent raids in February 2026)","Foro oficial — Perfect Your Pokédex: everything you can register (comunidad; indica que Cobalion, Terrakion y Virizion se añadieron como incursiones permanentes en febrero de 2026)","官方论坛 — Perfect Your Pokédex: everything you can register（社区；称勾帕路翁、代拉基翁和毕力吉翁于 2026 年 2 月加入常驻团体战）"],
